    },
    [41] = {
      beijing = 3950,
      dialog = 3,
      music = "205_XuMo_Second",
      renwu = "npc",
      sentence = "A long time ago at that press conference, he had also been met with such scrutiny. But this time, I didn't plan to join the ranks of the scrutineers.",
